import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Create plane geometry
  // Atlas region 512×320 → aspect ratio 1.6:1
  const geometry = new THREE.PlaneGeometry(3.2, 2.0);

  // Load texture
  let texture = null;
  if (config.assets?.imageUrl) {
    texture = ctx.textureLoader.load(config.assets.imageUrl);
    texture.colorSpace = THREE.SRGBColorSpace;
  }

  // Create TSL material
  const colorNode = texture
    ? uniform(texture)
    : uniform(new THREE.Color(0xe8ecf2)); // paper fallback

  const material = new MeshBasicNodeMaterial({
    colorNode,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide
  });

  // Create plane mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text content
  if (ctx.fontAtlas && config.textContent) {
    let text = 'Pricing';

    // Parse text from config
    if (Array.isArray(config.textContent)) {
      const first = config.textContent[0];
      text = (first?.text || first) ?? text;
    } else if (typeof config.textContent === 'string') {
      text = config.textContent;
    } else if (config.textContent?.text) {
      text = config.textContent.text;
    }

    // Create text mesh
    const textMesh = ctx.fontAtlas.createTextMesh({
      text,
      fontSize: 0.96,
      fontWeight: 400,
      fontFamily: 'Lora',
      color: 0x16161d,
      align: 'center'
    });

    if (textMesh) {
      textMesh.position.z = 0.1;
      group.add(textMesh);
    }
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
  };

  group.userData.handlers = {};

  return group;
}
